CREATE OR REPLACE PROCEDURE sp_approvals_submit_for_approval ( p_project_id numeric, p_approval_type_id numeric, p_team_member_id numeric, p_justification varchar, p_project_approval_id out numeric ) AS $body$
DECLARE

  c1 RECORD;
  c2 RECORD;

BEGIN
    for c1 in (
        select i.id initiative_approval_id,
               (select count(*) from sp_initiative_approval_chain
                 where initiative_approval_id = i.id
                   and active_yn = 'Y') approvers_cnt
          from sp_projects p,
               sp_initiative_approvals i
         where p.id = p_project_id
           and p.initiative_id = i.initiative_id
           and i.approval_type_id = p_approval_type_id
    ) loop
        insert into sp_project_approvals(approval_type_id, project_id, submitted_by_team_member_id, justification, initiative_approval_id)
        values (p_approval_type_id, p_project_id, p_team_member_id, p_justification, c1.initiative_approval_id)
        returning id into p_project_approval_id;

        commit;

        if coalesce(c1.initiative_approval_id::text, '') = '' then
            -- no approval chain
            update sp_project_approvals
               set status = 'NO-APPROVAL'
             where id = p_project_approval_id;
        elsif c1.approvers_cnt = 0 then
            -- no approvers
            update sp_project_approvals
               set status = 'NO-APPROVERS'
             where id = p_project_approval_id;
        else
            -- if submittor is in approval chain, start after that person
            for c2 in (
                select id
                  from sp_initiative_approval_chain
                 where initiative_approval_id = c1.initiative_approval_id
                   and (team_member_id = p_team_member_id or (alternate_team_member_id = p_team_member_id and
                         coalesce(alternate_start_date,clock_timestamp()) <= clock_timestamp() and
                         coalesce(alternate_end_date,clock_timestamp())+1 > clock_timestamp()) )
                   and active_yn = 'Y' 
            ) loop
                insert into sp_project_approval_chain(project_approval_id, initiative_approval_chain_id, team_member_id, status)
                values (p_project_approval_id, c2.id, p_team_member_id, 'APPROVED');
                commit;
            end loop;
        end if;
    end loop;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_approvals_submit_for_approval ( p_project_id numeric, p_approval_type_id numeric, p_team_member_id numeric, p_justification varchar, p_project_approval_id out numeric ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_approvals_clarify ( p_project_approval_chain_id numeric, p_team_member_id numeric, p_response varchar ) AS $body$
DECLARE

    l_project_approval_id  numeric;

BEGIN
    insert into sp_project_approval_chain(project_approval_id, initiative_approval_chain_id,
         team_member_id, comments,
         response, response_by_team_member_id,
         status, last_status_on,
         final_yn)
    SELECT project_approval_id, initiative_approval_chain_id,  
           team_member_id, comments, 
           p_response, p_team_member_id,
           'CLARIFICATION-REQUESTED', clock_timestamp(),
           'N'
      from sp_project_approval_chain
     where id = p_project_approval_chain_id;

    update sp_project_approval_chain
       set status = 'PENDING',
           last_status_on = clock_timestamp(),
           comments  = NULL
     where id = p_project_approval_chain_id
     returning project_approval_id into l_project_approval_id;

     update sp_project_approvals
        set status = 'PENDING'
      where id = l_project_approval_id;

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_approvals_clarify ( p_project_approval_chain_id numeric, p_team_member_id numeric, p_response varchar ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_approvals_withdraw ( p_project_approval_id numeric, p_team_member_id numeric ) AS $body$
DECLARE

    l_project_approval_id  numeric;

BEGIN
    update sp_project_approvals
       set status = 'WITHDRAWN',
           withdrawn_by_team_member_id = p_team_member_id
     where id = p_project_approval_id;

    update sp_project_approval_chain
       set final_yn = 'N'
     where project_approval_id = p_project_approval_id
       and final_yn != 'N';

    -- removing fk to allow for approval chain changes over time (team_member is always known)
    update sp_project_approval_chain
       set initiative_approval_chain_id  = NULL
     where project_approval_id = p_project_approval_id
       and (initiative_approval_chain_id IS NOT NULL AND initiative_approval_chain_id::text <> '');

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_approvals_withdraw ( p_project_approval_id numeric, p_team_member_id numeric ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION sp_approvals_approval_pending ( p_project_id numeric, p_team_member_id numeric ) RETURNS numeric AS $body$
DECLARE

  c1 RECORD;

BEGIN
    for c1 in (
        SELECT c.id
          from sp_project_approval_chain c,
               sp_project_approvals a
         where a.id = c.project_approval_id
           and a.project_id = p_project_id
           and c.team_member_id = p_team_member_id
           and c.status = 'PENDING'
           and c.final_yn = 'Y'
    ) loop
        return c1.id;
    end loop;

    return null;
END;
