-- Oracle package 'sp_comment_util' declaration, please edit to match PostgreSQL syntax.





-- this removes images from abandoned comments (ie. comments never created but images uploaded)
--   this is executed each time a comment is scanned to avoid the need for a job to do the cleanup
CREATE OR REPLACE PROCEDURE sp_comment_util_cleanup_old_images () AS $body$
BEGIN
    delete from sp_comment_images
     where image_ref_id not in (SELECT image_ref_id
              from sp_initiative_comments
             where (image_ref_id IS NOT NULL AND image_ref_id::text <> '') 
             
union all

            SELECT image_ref_id 
              from sp_project_comments
             where (image_ref_id IS NOT NULL AND image_ref_id::text <> '') 
             
union all

            select image_ref_id 
              from sp_task_comments
             where (image_ref_id IS NOT NULL AND image_ref_id::text <> '') 
             
union all

            select image_ref_id 
              from sp_release_comments
             where (image_ref_id IS NOT NULL AND image_ref_id::text <> '') 
             
union all

            select image_ref_id 
              from sp_init_focus_area_comments
             where (image_ref_id IS NOT NULL AND image_ref_id::text <> '')  )
       and created < clock_timestamp() - interval '1 days';
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_comment_util_cleanup_old_images () FROM PUBLIC;


-- this finds all the names of images within a clob
CREATE OR REPLACE FUNCTION sp_comment_util_find_images ( p_clob text ) RETURNS varchar AS $body$
DECLARE

    l_clob                text;
    l_clob_length         numeric;
    l_image_prefix        varchar(255)  := ']('||sp_util_get_setting(p_static_id => 'GET_COMMENT_IMAGE_PREFIX')||'get-image?x01=';
    l_prefix_length       numeric         := length(l_image_prefix);
    l_image_list          varchar(4000) := null;
    l_start               numeric        := 1;
    l_match               numeric;
    l_image_name          varchar(255);
    l_loop_count          numeric        := 0;
    l_max_loops           numeric        := 100;

BEGIN
    -- remove session placeholder (if it exists)
    l_clob := replace(p_clob,'session='||current_setting('sp_comment_util.g_session_placeholder')::varchar(20)||'&','');
    -- Get the length of the input clob
    l_clob_length := octet_length(l_clob);
    -- Loop through the clob to extract image names
    while l_start <= l_clob_length loop
        if l_loop_count > l_max_loops then
            exit; -- prevent infinite loop
        end if;
        l_match := null;
        -- will find the beginning of the image string
        l_match := instr(l_clob, l_image_prefix, l_start, 1);
        exit when l_match = 0;
        -- extract the image name
        l_image_name := substr(l_clob, l_match + l_prefix_length, 22);
        -- Append to the image list
        if (l_image_list IS NOT NULL AND l_image_list::text <> '') then
            l_image_list := l_image_list || ':' || l_image_name;
        else
            l_image_list := l_image_name;
        end if;
        -- Move position forward to continue searching
        l_start := l_start + l_match + l_prefix_length + 22;
        l_loop_count := l_loop_count + 1;
    end loop;

    return l_image_list;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_comment_util_find_images ( p_clob text ) FROM PUBLIC;


-- this finds all the image links in a clob and replaces with [image], for use in IRs and emails
CREATE OR REPLACE FUNCTION sp_comment_util_replace_images ( p_clob text ) RETURNS text AS $body$
DECLARE

    l_clob_length         numeric;
    l_image_prefix        varchar(255);
    l_prefix_length       numeric;
    l_image_list          varchar(4000) := null;
    l_start               numeric        := 1;
    l_match               numeric;
    l_begin               numeric;
    l_image_name          varchar(255);
    l_alt_text            varchar(4000);
    l_filename            varchar(255);
    l_loop_count          numeric        := 0;
    l_max_loops           numeric        := 100;
    l_clob                text           := p_clob;
BEGIN
    -- Get the length of the input clob
    l_clob_length := octet_length(p_clob);

-- first check without session - if needed, a second loop using session
    for i in 1..2 loop
        if i = 1 then
           l_image_prefix   := ']('||sp_util_get_setting(p_static_id => 'GET_COMMENT_IMAGE_PREFIX')||'get-image?x01=';
           l_prefix_length  := length(l_image_prefix);
           l_start          := 1;
           l_loop_count     := 0;
        else
           -- Search again including session
           l_image_prefix   := ']('||sp_util_get_setting(p_static_id => 'GET_COMMENT_IMAGE_PREFIX')||'get-image?session='||current_setting('sp_comment_util.g_session_placeholder')::varchar(20)||'&x01=';
           l_prefix_length  := length(l_image_prefix);
           l_start          := 1;
           l_loop_count     := 0;
        end if;

        -- Loop through the clob to find and replace image names
        while l_start <= l_clob_length loop
            if l_loop_count > l_max_loops then
                exit; -- prevent infinite loop
            end if;
            l_match := null;
            -- will find the beginning of the image string
            l_match := instr(p_clob, l_image_prefix, l_start, 1);
            exit when l_match = 0;
            -- extract the image name
            l_image_name := substr(p_clob, l_match + l_prefix_length, 22);
            -- if no alt text added, find image name
            if substr(p_clob,l_match-2,2) = '![' then
               -- find filename of image, if was file and not screensnap
               -- if image gets delete from images table, editing the content will fail to save
               --    wrapping this allows l_filename to be null, which is handled during replacement
               begin
                   select filename
                     into STRICT l_filename
                     from sp_comment_images
                    where unique_filename = l_image_name;
               exception
                   when no_data_found then null;
               end;
               -- replace image link
               if coalesce(l_filename,'image.png') != 'image.png' then
                   -- if link was added to image, there will be extra square brackets
                   l_clob := replace(l_clob,'[!['||l_image_prefix||l_image_name||')]','['||l_filename||']');
                   l_clob := replace(l_clob,'!['||l_image_prefix||l_image_name||')','['||l_filename||']');
               else
                   -- if link was added to image, there will be extra square brackets
                   l_clob := replace(l_clob,'[!['||l_image_prefix||l_image_name||')]','[image]');
                   l_clob := replace(l_clob,'!['||l_image_prefix||l_image_name||')','[image]');
               end if;
               l_filename := null;
            else
                l_begin     := instr(p_clob, '![', -(l_clob_length-l_match), 1);
                l_alt_text  := substr(p_clob, l_begin+2, l_match-l_begin-2);
                -- if link was added to image, there will be extra square brackets
                l_clob      := replace(l_clob,'[!['||l_alt_text||l_image_prefix||l_image_name||')]','['||l_alt_text||']');
                l_clob      := replace(l_clob,'!['||l_alt_text||l_image_prefix||l_image_name||')','['||l_alt_text||']');
            end if;

            -- Move position forward to continue searching
            l_start := l_match + l_prefix_length + 22;
            l_loop_count := l_loop_count + 1;
        end loop;

        -- if any images replace then no need to check using session
        if (l_image_name IS NOT NULL AND l_image_name::text <> '') then
           return l_clob;
        end if;

    end loop;

    return l_clob;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_comment_util_replace_images ( p_clob text ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION sp_comment_util_replace_session_on_save ( p_body text ) RETURNS text AS $body$
BEGIN
    return regexp_replace(p_body, '(\?|&)(session=)([[:digit:]]+)', '\1\2' || current_setting('sp_comment_util.g_session_placeholder')::varchar(20), 'g');
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_comment_util_replace_session_on_save ( p_body text ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION sp_comment_util_replace_session_on_display ( p_body text, p_session_id numeric ) RETURNS text AS $body$
BEGIN
    return replace(p_body, 'session='||current_setting('sp_comment_util.g_session_placeholder')::varchar(20), 'session=' || p_session_id);
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_comment_util_replace_session_on_display ( p_body text, p_session_id numeric ) FROM PUBLIC;


-- images can be removed during edit or pasted in and then removed before create
--   this ensures those are removed
CREATE OR REPLACE PROCEDURE sp_comment_util_remove_orphan_images ( p_comment_id numeric, p_comment_type varchar ) AS $body$
DECLARE

    l_image_ref_id  numeric;
    l_body          text;
    l_image_list    varchar(4000);

BEGIN
    if p_comment_type = 'INITIATIVE' then
        select image_ref_id, body
          into STRICT l_image_ref_id, l_body
          from sp_initiative_comments
         where id = p_comment_id;
    elsif p_comment_type = 'PROJECT' then
        select image_ref_id, body
          into STRICT l_image_ref_id, l_body
          from sp_project_comments
         where id = p_comment_id;
    elsif p_comment_type = 'TASK' then
        select image_ref_id, body
          into STRICT l_image_ref_id, l_body
          from sp_task_comments
         where id = p_comment_id;
    elsif p_comment_type = 'RELEASE' then
        select image_ref_id, body
          into STRICT l_image_ref_id, l_body
          from sp_release_comments
         where id = p_comment_id;
    elsif p_comment_type = 'INIT_FOCUS_AREA' then
        select image_ref_id, body
          into STRICT l_image_ref_id, l_body
          from sp_init_focus_area_comments
         where id = p_comment_id;
    end if;

    if (l_image_ref_id IS NOT NULL AND l_image_ref_id::text <> '') and (l_body IS NOT NULL AND l_body::text <> '') then
        l_image_list := ':'||sp_comment_util_find_images(l_body)||':';

        delete from sp_comment_images
         where image_ref_id = l_image_ref_id
           and position(':'||unique_filename||':' in l_image_list) = 0;
    end if;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_comment_util_remove_orphan_images ( p_comment_id numeric, p_comment_type varchar ) FROM PUBLIC;

