CREATE OR REPLACE PROCEDURE sp_comment_util_update_initiative_comment ( p_comment_id numeric, p_comment varchar, p_private_yn varchar default 'N', p_image_ref_id numeric default null) AS $body$
DECLARE

    l_comment            text;
    l_comment_no_images  text;
    l_image_ref_id       numeric;
    l_image_list         varchar(4000);


BEGIN
    l_comment           := sp_comment_util_replace_session_on_save(p_comment);
    l_comment_no_images := sp_comment_util_replace_images(l_comment);

    -- for existing content, there may be no image_ref_id, so need to add one
    update sp_initiative_comments
       set body           = l_comment,
           body_html      = apex_markdown.to_html(l_comment),
           body_no_images = l_comment_no_images,
           private_yn     = p_private_yn,
           image_ref_id   = coalesce(image_ref_id,to_number(uuid_generate_v4(), 'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'))
     where id = p_comment_id
    returning image_ref_id into l_image_ref_id;

    l_image_list := sp_comment_util_find_images(l_comment);

    -- if no images found, no need to update references
    if (l_image_list IS NOT NULL AND l_image_list::text <> '') then
        -- updating image_ref_id to match that of the existing content
        update sp_comment_images
           set image_ref_id = l_image_ref_id
         where position(':'||unique_filename||':' in ':'||l_image_list||':') > 0
           and image_ref_id = p_image_ref_id;
    end if;

    -- doing image cleanup
    CALL sp_comment_util_remove_orphan_images(
        p_comment_id   => p_comment_id,
        p_comment_type => 'INITIATIVE');

    -- cleaning up old images, only on update
    CALL sp_comment_util_cleanup_old_images();

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_comment_util_update_initiative_comment ( p_comment_id numeric, p_comment varchar, p_private_yn varchar default 'N', p_image_ref_id numeric default null) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_comment_util_delete_initiative_comment ( p_comment_id numeric ) AS $body$
DECLARE

    l_image_ref_id  numeric;

BEGIN
    select image_ref_id
      into STRICT l_image_ref_id
      from sp_initiative_comments
     where id = p_comment_id;

    if (l_image_ref_id IS NOT NULL AND l_image_ref_id::text <> '') then
        delete from sp_comment_images
         where image_ref_id = l_image_ref_id;
    end if;

    delete from sp_initiative_comments
     where id = p_comment_id;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_comment_util_delete_initiative_comment ( p_comment_id numeric ) FROM PUBLIC;

