CREATE OR REPLACE PROCEDURE sp_comment_util_add_project_comment ( p_app_user_id numeric, p_app_user varchar, p_comment varchar, p_private_yn varchar default 'N', p_project_id numeric DEFAULT NULL, p_system_gen_yn varchar default 'N', p_app_id numeric default null, p_permalink_pre varchar default null, p_nomen_sp varchar default null, p_nomen_project varchar default null, p_image_ref_id numeric default null) AS $body$
DECLARE

    l_comment            text;
    l_comment_no_images  text;
    l_comment_id         numeric;
    l_email_comment      text;
    l_link               varchar(4000);
    l_mentions           varchar(4000);
  c1 RECORD;
  c2 RECORD;

BEGIN
    l_comment           := sp_comment_util_replace_session_on_save(p_comment);
    l_comment_no_images := sp_comment_util_replace_images(l_comment);

    insert into SP_PROJECT_COMMENTS(
        project_id,
        author_id, 
        body,
        body_html, 
        body_no_images, 
        private_yn,
        image_ref_id) 
    values (
        p_project_id,
        p_app_user_id,
        l_comment,
        apex_markdown.to_html(l_comment),
        l_comment_no_images,
        p_private_yn,
        p_image_ref_id)
    returning id into l_comment_id;
    commit;

    -- doing image cleanup
    CALL sp_comment_util_remove_orphan_images(
        p_comment_id   => l_comment_id,
        p_comment_type => 'PROJECT' );

    if p_private_yn = 'N' and p_system_gen_yn = 'N' then

        CALL sp_comment_util_set_comment_email_references(l_comment_id);

        l_email_comment := apex_markdown.to_html(substr(l_comment_no_images,1,3000)||case when length(l_comment_no_images) > 3000 then ' ...' end);

        for c1 in (
            SELECT p.project,
                   apex_escape.html(p.project) project_esc,
                   p.friendly_identifier fi, apex_escape.html(p.project_url_name) project_url_name, 
                   p.owner_id, apex_escape.html(t.first_name) first_name, t.screen_name
              FROM sp_projects p
LEFT OUTER JOIN sp_team_members t ON (p.owner_id = t.id)
WHERE p.id = p_project_id  ) loop
            l_link := p_permalink_pre||c1.fi||'&pn='||c1.project_url_name;
            if apex_util.get_build_option_status(p_application_id => p_app_id, p_build_option_name => 'Comment Tagging') = 'INCLUDE' then
                l_mentions := sp_util_find_mentions(l_comment_no_images);
                -- mentions (not current user)
                if (l_mentions IS NOT NULL AND l_mentions::text <> '') then
                    for c2 in (
                        SELECT id, apex_escape.html(first_name) first_name
                          from sp_team_members
                         where position(':'||screen_name||':' in ':'||l_mentions||':') > 0
                           and id != p_app_user_id and (screen_name IS NOT NULL AND screen_name::text <> '')
                    ) loop
                        CALL sp_util_comment_notification(
                            p_team_member_id => c2.id, 
                            p_app_name       => p_nomen_sp, 
                            p_app_id         => p_app_id,
                            p_title          => 'You were mentioned in a comment added to '||c1.project_esc,
                            p_project_id     => p_project_id, 
                            p_link           => l_link, 
                            p_view_what      => p_nomen_project,
                            p_email_contents => 'Hi '||c2.first_name||'<br/><br/>'||
                                                'You were mentioned in a new comment added to <a  style="font-weight:bold" href="'||l_link||'">'||c1.project_esc||'</a><br/>'||
                                                'Comment by: '||apex_escape.html(lower(p_app_user))||'<br/>'||
                                                l_email_comment,
                            p_notification_type => 'MENTION' );
                    end loop;
                end if;
            end if;

            -- owner (not current user and not tagged in comment)
            if (c1.owner_id IS NOT NULL AND c1.owner_id::text <> '') and
               c1.owner_id != p_app_user_id and 
               position(':'||c1.screen_name||':' in ':'||l_mentions||':') = 0 
            then
               CALL sp_util_comment_notification(
                    p_team_member_id => c1.owner_id, 
                    p_app_name       => p_nomen_sp,
                    p_app_id         => p_app_id,
                    p_title          => 'New comment added to '||c1.project_esc,
                    p_project_id     => p_project_id, 
                    p_link           => l_link, 
                    p_view_what      => p_nomen_project,
                    p_email_contents => 'Hi '||c1.first_name||'<br/><br/>'||
                                        'A new comment was just added to <a  style="font-weight:bold" href="'||l_link||'">'||c1.project_esc||'</a><br/>'||
                                        'Comment by: '||apex_escape.html(lower(p_app_user))||'<br/>'||
                                        l_email_comment,
                    p_notification_type => 'COMMENT' );
            end if;

            -- favorited (not owner, not current user and not tagged in comment)
            for c2 in (
                SELECT f.team_member_id, apex_escape.html(t.first_name) first_name
                  from sp_favorites f,
                       sp_team_members t
                 where f.project_id = p_project_id
                   and f.team_member_id = t.id
                   and f.team_member_id != p_app_user_id
                   and f.team_member_id != c1.owner_id
                   and (t.screen_name IS NOT NULL AND t.screen_name::text <> '')
                   and position(':'||t.screen_name||':' in ':'||l_mentions||':') = 0
            ) loop
                CALL sp_util_comment_notification(
                    p_team_member_id => c2.team_member_id, 
                    p_app_name       => p_nomen_sp,
                    p_app_id         => p_app_id,
                    p_title          => 'New comment added to '||c1.project_esc,
                    p_project_id     => p_project_id, 
                    p_link           => l_link, 
                    p_view_what      => p_nomen_project,
                    p_email_contents => 'Hi '||c2.first_name||'<br/><br/>'||
                                        'A new comment was just added to <a  style="font-weight:bold" href="'||l_link||'">'||c1.project_esc||'</a><br/>'||
                                        'Comment by: '||apex_escape.html(lower(p_app_user))||'<br/>'||
                                        l_email_comment,
                    p_notification_type => 'COMMENT' );
            end loop;
        end loop;
    end if;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_comment_util_add_project_comment ( p_app_user_id numeric, p_app_user varchar, p_comment varchar, p_private_yn varchar default 'N', p_project_id numeric DEFAULT NULL, p_system_gen_yn varchar default 'N', p_app_id numeric default null, p_permalink_pre varchar default null, p_nomen_sp varchar default null, p_nomen_project varchar default null, p_image_ref_id numeric default null) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_comment_util_update_project_comment ( p_comment_id numeric, p_comment varchar, p_private_yn varchar default 'N', p_image_ref_id numeric default null) AS $body$
DECLARE

    l_comment            text;
    l_comment_no_images  text;
    l_image_ref_id       numeric;
    l_image_list         varchar(4000);

BEGIN
    l_comment           := sp_comment_util_replace_session_on_save(p_comment);
    l_comment_no_images := sp_comment_util_replace_images(l_comment);

    -- for existing content, there may be no image_ref_id, so need to add one
    update sp_project_comments
       set body           = l_comment,
           body_html      = apex_markdown.to_html(l_comment),
           body_no_images = l_comment_no_images,
           private_yn     = p_private_yn,
           image_ref_id   = coalesce(image_ref_id,to_number(uuid_generate_v4(), 'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'))
     where id = p_comment_id
    returning image_ref_id into l_image_ref_id;

    l_image_list := sp_comment_util_find_images(l_comment);

    if (l_image_list IS NOT NULL AND l_image_list::text <> '') then
        -- updating image_ref_id to match that of the existing content
        update sp_comment_images
           set image_ref_id = l_image_ref_id
         where position(':'||unique_filename||':' in ':'||l_image_list||':') > 0
           and image_ref_id = p_image_ref_id;
    end if;

    -- doing image cleanup
    CALL sp_comment_util_remove_orphan_images(
        p_comment_id   => p_comment_id,
        p_comment_type => 'PROJECT');

    -- cleaning up old images, only on update
    CALL sp_comment_util_cleanup_old_images();

    if p_private_yn = 'N' then
        CALL sp_comment_util_set_comment_email_references(p_comment_id);
    end if;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_comment_util_update_project_comment ( p_comment_id numeric, p_comment varchar, p_private_yn varchar default 'N', p_image_ref_id numeric default null) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_comment_util_delete_project_comment ( p_comment_id numeric ) AS $body$
DECLARE

    l_image_ref_id  numeric;

BEGIN
    select image_ref_id
      into STRICT l_image_ref_id
      from sp_project_comments
     where id = p_comment_id;

    if (l_image_ref_id IS NOT NULL AND l_image_ref_id::text <> '') then
        delete from sp_comment_images
         where image_ref_id = l_image_ref_id;
    end if;

    delete from sp_project_comments
     where id = p_comment_id;
END;
