CREATE OR REPLACE PROCEDURE sp_comment_util_add_task_comment ( p_app_user_id numeric, p_app_user varchar, p_comment varchar, p_private_yn varchar default 'N', p_project_id numeric DEFAULT NULL, p_task_id numeric DEFAULT NULL, p_app_id numeric DEFAULT NULL, p_link varchar DEFAULT NULL, p_nomen_sp varchar DEFAULT NULL, p_image_ref_id numeric default null) AS $body$
DECLARE

    l_comment            text;
    l_comment_no_images  text;
    l_comment_id         numeric;
    l_email_comment      text;
    l_mentions           varchar(4000);
  c1 RECORD;
  c2 RECORD;

BEGIN
    l_comment           := sp_comment_util_replace_session_on_save(p_comment);
    l_comment_no_images := sp_comment_util_replace_images(l_comment);

    insert into sp_task_comments(
        task_id,
        author_id, 
        body,
        body_html, 
        body_no_images,
        private_yn,
        image_ref_id ) 
    values (
        p_task_id,
        p_app_user_id,
        l_comment,
        apex_markdown.to_html(l_comment),
        l_comment_no_images,
        p_private_yn,
        p_image_ref_id )
    returning id into l_comment_id;
    commit;

    -- doing image cleanup
    CALL sp_comment_util_remove_orphan_images(
        p_comment_id   => l_comment_id,
        p_comment_type => 'TASK' );

    if p_private_yn = 'N' then

        l_email_comment := apex_markdown.to_html(substr(l_comment_no_images,1,3000)||case when length(l_comment_no_images) > 3000 then ' ...' end);

        for c1 in (
            SELECT p.project,
                   apex_escape.html(p.project) project_esc,
                   apex_escape.html((SELECT task_type from sp_task_types rt where rt.id = a.task_type_id)||
                                     (case when (a.task_sub_type_id IS NOT NULL AND a.task_sub_type_id::text <> '') then ': ' end) ||
                                     (select task_type from sp_task_types rt where rt.id = a.task_sub_type_id) ||
                                     case when (a.task IS NOT NULL AND a.task::text <> '') then ' - '||a.task end) task_name,
                   apex_escape.html(select rt.task_type
                                       from sp_task_types rt
                                      where a.id = p_task_id
                                        and rt.id = a.task_type_id) parent_task_type,
                   p.owner_id, apex_escape.html(t.first_name) first_name, t.screen_name
              FROM sp_tasks a, sp_projects p
LEFT OUTER JOIN sp_team_members t ON (p.owner_id = t.id)
WHERE p.id = p_project_id and a.id = p_task_id  ) loop
            if apex_util.get_build_option_status(p_application_id => p_app_id, p_build_option_name => 'Comment Tagging') = 'INCLUDE' then
                l_mentions := sp_util_find_mentions(l_comment_no_images);
                -- mentions (not current user)
                if (l_mentions IS NOT NULL AND l_mentions::text <> '') then
                    for c2 in (
                        SELECT id, first_name
                          from sp_team_members
