                           and id != p_app_user_id
                           and (screen_name IS NOT NULL AND screen_name::text <> '') 
                    ) loop
                        CALL sp_util_comment_notification(
                            p_team_member_id => c2.id, 
                            p_app_name       => p_nomen_sp, 
                            p_app_id         => p_app_id,
                            p_title          => 'You were mentioned in a comment added to '||c1.project_esc||' - '||c1.task_name,
                            p_project_id     => p_project_id, 
                            p_task_id        => p_task_id,
                            p_link           => p_link, 
                            p_view_what      => c1.parent_task_type,
                            p_email_contents => 'Hi '||c2.first_name||'<br/><br/>'||
                                                'You were mentioned in a new comment added to '||c1.project_esc||' - <a  style="font-weight:bold" href="'||p_link||'">'||apex_escape.html(c1.task_name)||'</a><br/>'||
                                                'Comment by: '||apex_escape.html(lower(p_app_user))||'<br/>'||
                                                l_email_comment,
                            p_notification_type => 'MENTION' );
                    end loop;
                end if;
            end if;

            -- owner (not current user and not tagged in comment)
            if (c1.owner_id IS NOT NULL AND c1.owner_id::text <> '') and
               c1.owner_id != p_app_user_id and 
               position(':'||c1.screen_name||':' in ':'||l_mentions||':') = 0 
            then
               CALL sp_util_comment_notification(
                    p_team_member_id => c1.owner_id, 
                    p_app_name       => p_nomen_sp,
                    p_app_id         => p_app_id,
                    p_title          => 'New comment added to '||c1.project_esc||' - '||c1.task_name,
                    p_project_id     => p_project_id, 
                    p_task_id        => p_task_id,
                    p_link           => p_link, 
                    p_view_what      => c1.parent_task_type,
                    p_email_contents => 'Hi '||c1.first_name||'<br/><br/>'||
                                        'A new comment was just added to '||c1.project_esc||' - <a  style="font-weight:bold" href="'||p_link||'">'||apex_escape.html(c1.task_name)||'</a><br/>'||
                                        'Comment by: '||apex_escape.html(lower(p_app_user))||'<br/>'||
                                        l_email_comment,
                    p_notification_type => 'COMMENT' );
            end if;

            -- task owner (not project owner, current user and not tagged in comment)
            for c2 in (
                SELECT a.owner_id team_member_id, apex_escape.html(t.first_name) first_name
                  from sp_tasks a,
                       sp_team_members t
                 where a.id = p_task_id
                   and a.owner_id = t.id
                   and a.owner_id != p_app_user_id
                   and a.owner_id != c1.owner_id
                   and position(':'||t.screen_name||':' in ':'||l_mentions||':') = 0
            ) loop
                CALL sp_util_comment_notification(
                    p_team_member_id => c2.team_member_id, 
                    p_app_name       => p_nomen_sp,
                    p_app_id         => p_app_id,
                    p_title          => 'New comment added to '||c1.project_esc||' - '||c1.task_name,
                    p_project_id     => p_project_id, 
                    p_task_id        => p_task_id,
                    p_link           => p_link, 
                    p_view_what      => c1.parent_task_type,
                    p_email_contents => 'Hi '||c2.first_name||'<br/><br/>'||
                                        'A new comment was just added to '||c1.project_esc||' - <a  style="font-weight:bold" href="'||p_link||'">'||apex_escape.html(c1.task_name)||'</a><br/>'||
                                        'Comment by: '||apex_escape.html(lower(p_app_user))||'<br/>'||
                                        l_email_comment,
                    p_notification_type => 'COMMENT' );
            end loop;

            -- favorited (not owner, not current user and not tagged in comment)
            for c2 in (
                SELECT f.team_member_id, apex_escape.html(t.first_name) first_name
                  from sp_favorites f,
                       sp_team_members t
                 where f.project_id = p_project_id
                   and f.team_member_id = t.id
                   and f.team_member_id != p_app_user_id
                   and f.team_member_id != c1.owner_id
                   and (t.screen_name IS NOT NULL AND t.screen_name::text <> '')
                   and position(':'||t.screen_name||':' in ':'||l_mentions||':') = 0
            ) loop
                CALL sp_util_comment_notification(
                    p_team_member_id => c2.team_member_id, 
                    p_app_name       => p_nomen_sp,
                    p_app_id         => p_app_id,
                    p_title          => 'New comment added to '||c1.project_esc||' - '||c1.task_name,
                    p_project_id     => p_project_id, 
                    p_task_id        => p_task_id,
                    p_link           => p_link, 
                    p_view_what      => c1.parent_task_type,
                    p_email_contents => 'Hi '||c2.first_name||'<br/><br/>'||
                                        'A new comment was just added to '||c1.project_esc||' - <a  style="font-weight:bold" href="'||p_link||'">'||apex_escape.html(c1.task_name)||'</a><br/>'||
                                        'Comment by: '||apex_escape.html(lower(p_app_user))||'<br/>'||
                                        l_email_comment,
                    p_notification_type => 'COMMENT' );
            end loop;
        end loop;
    end if;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_comment_util_add_task_comment ( p_app_user_id numeric, p_app_user varchar, p_comment varchar, p_private_yn varchar default 'N', p_project_id numeric DEFAULT NULL, p_task_id numeric DEFAULT NULL, p_app_id numeric DEFAULT NULL, p_link varchar DEFAULT NULL, p_nomen_sp varchar DEFAULT NULL, p_image_ref_id numeric default null) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_comment_util_update_task_comment ( p_comment_id numeric, p_comment varchar, p_private_yn varchar default 'N', p_image_ref_id numeric default null) AS $body$
DECLARE

    l_comment            text;
    l_comment_no_images  text;
    l_image_ref_id       numeric;
    l_image_list         varchar(4000);

BEGIN
    l_comment           := sp_comment_util_replace_session_on_save(p_comment);
    l_comment_no_images := sp_comment_util_replace_images(l_comment);

    -- for existing content, there may be no image_ref_id, so need to add one
    update sp_task_comments
       set body           = l_comment,
           body_html      = apex_markdown.to_html(l_comment),
           body_no_images = l_comment_no_images,
           private_yn     = p_private_yn,
           image_ref_id   = coalesce(image_ref_id,to_number(uuid_generate_v4(), 'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'))
     where id = p_comment_id
    returning image_ref_id into l_image_ref_id;

    l_image_list := sp_comment_util_find_images(l_comment);

    if (l_image_list IS NOT NULL AND l_image_list::text <> '') then
        -- updating image_ref_id to match that of the existing content
        update sp_comment_images
           set image_ref_id = l_image_ref_id
         where position(':'||unique_filename||':' in ':'||l_image_list||':') > 0
           and image_ref_id = p_image_ref_id;
    end if;

    -- doing image cleanup
    CALL sp_comment_util_remove_orphan_images(
        p_comment_id   => p_comment_id,
        p_comment_type => 'TASK');

    -- cleaning up old images, only on update
    CALL sp_comment_util_cleanup_old_images();

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_comment_util_update_task_comment ( p_comment_id numeric, p_comment varchar, p_private_yn varchar default 'N', p_image_ref_id numeric default null) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_comment_util_delete_task_comment ( p_comment_id numeric ) AS $body$
DECLARE

    l_image_ref_id  numeric;

BEGIN
    select image_ref_id
      into STRICT l_image_ref_id
      from sp_task_comments
     where id = p_comment_id;

    if (l_image_ref_id IS NOT NULL AND l_image_ref_id::text <> '') then
        delete from sp_comment_images
         where image_ref_id = l_image_ref_id;
    end if;

    delete from sp_task_comments
     where id = p_comment_id;
END;
$body$
LANGUAGE PLPGSQL
;
