--
-- dblink wrapper to call function sp_util_add_error_log as an autonomous transaction
--
CREATE EXTENSION IF NOT EXISTS dblink;

CREATE OR REPLACE PROCEDURE sp_util_add_error_log ( p_package_name varchar, p_procedure_name varchar, p_error varchar, p_arg1_name varchar default null, p_arg1_val varchar default null, p_arg2_name varchar default null, p_arg2_val varchar default null, p_arg3_name varchar default null, p_arg3_val varchar default null, p_arg4_name varchar default null, p_arg4_val varchar default null, p_arg5_name varchar default null, p_arg5_val varchar default null) AS $body$
DECLARE
	-- Change this to reflect the dblink connection string
	v_conn_str  text := format('port=%s dbname=%s user=%s', current_setting('port'), current_database(), current_user);
	v_query     text;

BEGIN
	v_query := 'CALL sp_util_add_error_log_atx ( ' || quote_nullable(p_package_name) || ',' || quote_nullable(p_procedure_name) || ',' || quote_nullable(p_error) || ',' || quote_nullable(p_arg1_name) || ',' || quote_nullable(p_arg1_val) || ',' || quote_nullable(p_arg2_name) || ',' || quote_nullable(p_arg2_val) || ',' || quote_nullable(p_arg3_name) || ',' || quote_nullable(p_arg3_val) || ',' || quote_nullable(p_arg4_name) || ',' || quote_nullable(p_arg4_val) || ',' || quote_nullable(p_arg5_name) || ',' || quote_nullable(p_arg5_val) || ' )';
	PERFORM * FROM dblink(v_conn_str, v_query) AS p (ret boolean);

END;
$body$ LANGUAGE plpgsql SECURITY DEFINER;




CREATE OR REPLACE PROCEDURE sp_util_add_error_log_atx ( p_package_name varchar, p_procedure_name varchar, p_error varchar, p_arg1_name varchar default null, p_arg1_val varchar default null, p_arg2_name varchar default null, p_arg2_val varchar default null, p_arg3_name varchar default null, p_arg3_val varchar default null, p_arg4_name varchar default null, p_arg4_val varchar default null, p_arg5_name varchar default null, p_arg5_val varchar default null) AS $body$
BEGIN

    insert into sp_error_log(package_name, procedure_name, error, 
        arg1_name, arg1_val, arg2_name, arg2_val, arg3_name, arg3_val, 
        arg4_name, arg4_val, arg5_name, arg5_val ) 
    values (substr(p_package_name,1,255), substr(p_procedure_name,1,500), substr(p_error,1,4000), 
        substr(p_arg1_name,1,255), substr(p_arg1_val,1,4000), substr(p_arg2_name,1,255), substr(p_arg2_val,1,4000), 
        substr(p_arg3_name,1,255), substr(p_arg3_val,1,4000), substr(p_arg4_name,1,255), substr(p_arg4_val,1,4000), 
        substr(p_arg5_name,1,255), substr(p_arg5_val,1,4000) );
    commit;

    -- g_error_retention_in_days is in the spec
    delete from sp_error_log
     where created_trunc < clock_timestamp() - current_setting('sp_util.g_error_retention_in_days')::numeric;
    commit;

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_add_error_log ( p_package_name varchar, p_procedure_name varchar, p_error varchar, p_arg1_name varchar default null, p_arg1_val varchar default null, p_arg2_name varchar default null, p_arg2_val varchar default null, p_arg3_name varchar default null, p_arg3_val varchar default null, p_arg4_name varchar default null, p_arg4_val varchar default null, p_arg5_name varchar default null, p_arg5_val varchar default null) FROM PUBLIC; -- REVOKE ALL ON PROCEDURE sp_util_add_error_log_atx ( p_package_name varchar, p_procedure_name varchar, p_error varchar, p_arg1_name varchar default null, p_arg1_val varchar default null, p_arg2_name varchar default null, p_arg2_val varchar default null, p_arg3_name varchar default null, p_arg3_val varchar default null, p_arg4_name varchar default null, p_arg4_val varchar default null, p_arg5_name varchar default null, p_arg5_val varchar default null) FROM PUBLIC;



