CREATE OR REPLACE PROCEDURE sp_util_copy_release ( p_copy_from_release_id numeric, p_new_release varchar, p_push_days numeric, p_new_release_id out numeric ) AS $body$
DECLARE

  c1 RECORD;

BEGIN
    for c1 in (
        select release_train, release_owner_id,
               release_target_date, release_open_date,
               description
          from sp_release_trains
         where id = p_copy_from_release_id
    ) loop
        insert into sp_release_trains(release_train, release_owner_id, release,
             release_target_date, release_open_date,
             description)
        values (c1.release_train, c1.release_owner_id, p_new_release, 
             c1.release_target_date + p_push_days, c1.release_open_date + p_push_days,
             c1.description)
            returning id into p_new_release_id;
    end loop;

    insert into sp_release_milestones(release_id, milestone_name, upper_milestone_name,
        milestone_date, milestone_description)
    SELECT p_new_release_id, milestone_name, upper_milestone_name, 
           milestone_date + p_push_days, milestone_description
      from sp_release_milestones
     where release_id = p_copy_from_release_id;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_copy_release ( p_copy_from_release_id numeric, p_new_release varchar, p_push_days numeric, p_new_release_id out numeric ) FROM PUBLIC;



