CREATE OR REPLACE FUNCTION sp_util_copy_project ( p_project_id numeric, p_new_project_name varchar ) RETURNS numeric AS $body$
DECLARE

    l_project_id           numeric;
  c1 RECORD;

BEGIN

    -- forced to use cursor to do insert into select returning
    for c1 in (
        select initiative_id,
               owner_id,
               status_scale,
               priority_id,
               project_size,
               description,
               requires_reviews_yn,
               doc_impact_yn,
               focus_area_id,
               project_group_id,
               tags
          from sp_projects
         where id = p_project_id
    ) loop
        insert into sp_projects(
               initiative_id,
               project,
               owner_id,
               status_scale,
               pct_complete,
               --
               priority_id,
               project_size,
               description,
               --
               requires_reviews_yn,
               doc_impact_yn,
               focus_area_id,
               project_group_id,
               tags )
        values (
               c1.initiative_id,
               p_new_project_name,
               c1.owner_id,
               c1.status_scale,
               10,
               --
               c1.priority_id,
               c1.project_size,
               c1.description,
               --
               c1.requires_reviews_yn,
               c1.doc_impact_yn,
               c1.focus_area_id,
               c1.project_group_id,
               c1.tags )
        returning id into l_project_id;
    end loop;

    CALL sp_util_default_project_tasks(p_project_id => l_project_id);

    insert into sp_project_contributors(
           project_id,
           team_member_id,
           responsibility_id,
           responsibility,
           tags )
    SELECT l_project_id,
           team_member_id,
           responsibility_id,
           responsibility, 
           tags
      from sp_project_contributors
     where project_id = p_project_id;

    return l_project_id;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_util_copy_project ( p_project_id numeric, p_new_project_name varchar ) FROM PUBLIC;



