CREATE OR REPLACE PROCEDURE sp_util_default_project_tasks ( p_project_id numeric) AS $body$
BEGIN
    insert into sp_tasks(project_id, task_type_id, task_sub_type_id, status_id)
    SELECT p.id,
           coalesce(tt.parent_type_id,tt.id),
           case when (tt.parent_type_id IS NOT NULL AND tt.parent_type_id::text <> '') then tt.id end,
           (SELECT min(id) from sp_task_statuses
             where is_default_yn = 'Y'
               and task_type_id = tt.parent_type_id)
      from sp_projects p,
           sp_initiatives i,
           sp_initiative_default_tasks dt,
           sp_task_types tt
     where p.id = p_project_id
       and p.initiative_id = i.id
       and i.id = dt.initiative_id
       and dt.type_id = tt.id
       and tt.include_yn = 'Y';
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_default_project_tasks ( p_project_id numeric) FROM PUBLIC;



