CREATE OR REPLACE FUNCTION sp_util_get_user_email ( p_app_user varchar default null, p_user_id numeric default null) RETURNS varchar AS $body$
DECLARE

    l_email varchar(255) := null;
  c1 RECORD;

BEGIN
    for c1 in (
        SELECT email
          from sp_team_members 
         where email = lower(p_app_user)
            or id = p_user_id 
    ) loop
        l_email := c1.email;
        exit;
    end loop;
    return l_email;
END;
