CREATE OR REPLACE FUNCTION sp_util_get_user_id ( p_app_user varchar default null, p_screen_name varchar default null) RETURNS numeric AS $body$
DECLARE

    l_id numeric := null;
  c1 RECORD;

BEGIN
    for c1 in (
        SELECT id
          from sp_team_members 
         where email = lower(p_app_user)
            or screen_name = lower(p_screen_name) 
    ) loop
