CREATE OR REPLACE PROCEDURE sp_util_add_setting ( p_static_id varchar, p_description varchar, p_setting_value varchar, p_is_numeric_yn varchar, p_is_yn varchar ) AS $body$
BEGIN

    if p_is_numeric_yn = 'Y' and p_is_yn = 'Y' then
        RAISE EXCEPTION '%', 'Setting cannot be both numeric and YN.' USING ERRCODE = '45111';
    end if;

    insert into sp_app_settings(static_id, description, is_numeric_yn, is_yn) 
    values (p_static_id, p_description, p_is_numeric_yn, p_is_yn);
 
    CALL sp_util_set_setting(p_static_id => p_static_id, p_setting_value => p_setting_value);

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_add_setting ( p_static_id varchar, p_description varchar, p_setting_value varchar, p_is_numeric_yn varchar, p_is_yn varchar ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_util_set_setting ( p_static_id varchar, p_setting_value varchar ) AS $body$
DECLARE

  c1 RECORD;

BEGIN
  
    for c1 in ( 
        SELECT id, 
               setting_value,
               is_numeric_yn, 
               is_yn 
          from sp_app_settings  
         where static_id = upper(p_static_id)  
    ) loop 
        if c1.is_numeric_yn = 'Y' and validate_conversion(p_setting_value as numeric) = 0 then 
                RAISE EXCEPTION '%', 'Value must be numeric.' USING ERRCODE = '45111';
        elsif c1.is_yn = 'Y' and p_setting_value not in ('Y','N') then  
            RAISE EXCEPTION '%', 'Value must be Y or N.' USING ERRCODE = '45111';
        end if;
        update sp_app_settings  
           set setting_value = p_setting_value  
         where id = c1.id
           and (p_setting_value != c1.setting_value or coalesce(c1.setting_value::text, '') = '' or coalesce(p_setting_value::text, '') = '');
    end loop;

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_set_setting ( p_static_id varchar, p_setting_value varchar ) FROM PUBLIC;



