CREATE OR REPLACE PROCEDURE sp_util_set_ai_prompt ( p_static_id varchar, p_prompt text ) AS $body$
DECLARE

  c1 RECORD;

BEGIN
  
    for c1 in ( 
        SELECT id, prompt 
          from sp_ai_prompts  
         where static_id = upper(p_static_id)  
    ) loop 
        if (coalesce(c1.prompt::text, '') = '' and (p_prompt IS NOT NULL AND p_prompt::text <> '')) or ((c1.prompt IS NOT NULL AND c1.prompt::text <> '') and coalesce(p_prompt::text, '') = '') or
           c1.prompt != p_prompt
        then 
            update sp_ai_prompts 
               set prompt = p_prompt  
             where id = c1.id;
        end if;
    end loop;

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_set_ai_prompt ( p_static_id varchar, p_prompt text ) FROM PUBLIC;



