CREATE OR REPLACE PROCEDURE sp_util_notification_opt_in ( p_team_member_id numeric, p_notification_id numeric, p_frequency varchar default 'WEEKLY', p_release_id numeric default null) AS $body$
DECLARE

  c1 RECORD;

BEGIN
    for c1 in (
        select count(*) cnt
          from sp_notification_subscriptions
         where team_member_id = p_team_member_id
           and notification_id = p_notification_id
           and (release_id = p_release_id or coalesce(p_release_id::text, '') = '')
    ) loop
        if c1.cnt = 0 then
            insert into sp_notification_subscriptions(team_member_id, notification_id, frequency, release_id, opted_in_yn)
            values (p_team_member_id, p_notification_id, p_frequency, p_release_id, 'Y');
        else
            update sp_notification_subscriptions
               set opted_in_yn = 'Y'
             where team_member_id = p_team_member_id
               and notification_id = p_notification_id
               and (release_id = p_release_id or coalesce(p_release_id::text, '') = '');
            update sp_notification_subscriptions
               set frequency = p_frequency
             where team_member_id = p_team_member_id
               and notification_id = p_notification_id
               and (release_id = p_release_id or coalesce(p_release_id::text, '') = '')
               and frequency != p_frequency;
        end if;
    end loop;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_notification_opt_in ( p_team_member_id numeric, p_notification_id numeric, p_frequency varchar default 'WEEKLY', p_release_id numeric default null) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_util_notification_opt_out ( p_team_member_id numeric, p_notification_id numeric, p_release_id numeric default null) AS $body$
DECLARE

  c1 RECORD;

BEGIN
    for c1 in (
        SELECT id
          from sp_notification_subscriptions
         where team_member_id = p_team_member_id
           and notification_id = p_notification_id
           and (release_id = p_release_id or coalesce(p_release_id::text, '') = '')
    ) loop
        update sp_notification_subscriptions
           set opted_in_yn = 'N'
         where id = c1.id
           and opted_in_yn != 'N';
    end loop;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_notification_opt_out ( p_team_member_id numeric, p_notification_id numeric, p_release_id numeric default null) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_util_get_create_project_qp ( p_app_user varchar, p_quick_pick_id_1 out numeric, p_quick_pick_1 out varchar, p_quick_pick_id_2 out numeric, p_quick_pick_2 out varchar, p_quick_pick_id_3 out numeric, p_quick_pick_3 out varchar, p_quick_pick_id_4 out numeric, p_quick_pick_4 out varchar ) AS $body$
DECLARE

    c numeric := 0;
    l_quick_pick_id_1   numeric        := null;
    l_quick_pick_1      varchar(255) := null;
    l_quick_pick_id_2   numeric        := null;
    l_quick_pick_2      varchar(255) := null;
    l_quick_pick_id_3   numeric        := null;
    l_quick_pick_3      varchar(255) := null;
    l_quick_pick_id_4   numeric        := null;
    l_quick_pick_4      varchar(255) := null;
    l_app_user_id       numeric        := null;
    l_app_user          varchar(255) := null;
  c1 RECORD;

BEGIN
    -- get top 4 project owners
    for c1 in (
        SELECT t.first_name||' '||t.last_name||' ('||t.email||')' n, p.owner_id, count(*) c 
        from sp_projects p, sp_team_members t 
        where p.owner_id = t.id 
        group by t.first_name||' '||t.last_name||' ('||t.email||')', p.owner_id 
        order by 3 desc 
        fetch first 5 rows only) loop
            c := c + 1;
            if c = 1 then
                l_quick_pick_id_1 := c1.owner_id;
                l_quick_pick_1    := c1.n;
            elsif c = 2 then
                l_quick_pick_id_2 := c1.owner_id;
                l_quick_pick_2    := c1.n;
            elsif c = 3 then
                l_quick_pick_id_3 := c1.owner_id;
                l_quick_pick_3    := c1.n;
            elsif c = 4 then
                l_quick_pick_id_4 := c1.owner_id;
                l_quick_pick_4    := c1.n;
            end if;
    end loop;

    -- make sure the current user is on the list
    for c1 in (SELECT id, t.first_name||' '||t.last_name||' ('||t.email||')' n from SP_TEAM_MEMBERS t where t.email = lower(p_app_user) ) loop
        l_app_user_id := c1.id;
        l_app_user := c1.n;
    end loop;
    if l_app_user_id = l_quick_pick_id_1 or
       l_app_user_id = l_quick_pick_id_2 or 
       l_app_user_id = l_quick_pick_id_3 or 
       l_app_user_id = l_quick_pick_id_4 then
        null;
    else
       l_quick_pick_id_4 := l_app_user_id;
       l_quick_pick_4 := l_app_user;
    end if;

    -- set return values
    p_quick_pick_id_1  := l_quick_pick_id_1;
    p_quick_pick_1     := l_quick_pick_1;
    p_quick_pick_id_2  := l_quick_pick_id_2;
    p_quick_pick_2     := l_quick_pick_2;
    p_quick_pick_id_3  := l_quick_pick_id_3;
    p_quick_pick_3     := l_quick_pick_3;
    p_quick_pick_id_4  := l_quick_pick_id_4;
    p_quick_pick_4     := l_quick_pick_4;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_get_create_project_qp ( p_app_user varchar, p_quick_pick_id_1 out numeric, p_quick_pick_1 out varchar, p_quick_pick_id_2 out numeric, p_quick_pick_2 out varchar, p_quick_pick_id_3 out numeric, p_quick_pick_3 out varchar, p_quick_pick_id_4 out numeric, p_quick_pick_4 out varchar ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_util_get_current_username_and_id ( p_app_user varchar, p_users_name out varchar, p_users_id out numeric ) AS $body$
DECLARE

    l_users_name varchar(255) := null;
    l_users_id   numeric := null;
  c1 RECORD;

BEGIN
    for c1 in (SELECT first_name, last_name, id from SP_TEAM_MEMBERS where email = lower(p_app_user) ) loop 
        l_users_name := c1.first_name || ' ' || c1.last_name;
        l_users_id := c1.id;
    end loop;
    p_users_name := l_users_name;
    p_users_id := p_users_id;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_get_current_username_and_id ( p_app_user varchar, p_users_name out varchar, p_users_id out numeric ) FROM PUBLIC;

