CREATE OR REPLACE PROCEDURE sp_util_sync_team_members_app_role ( p_app_id numeric) AS $body$
DECLARE

  c1 RECORD;

BEGIN
    for c1 in (
       SELECT
           t.id,
           t.first_name,
           t.last_name,
           t.email,
           coalesce(t.APP_ROLE,'Unknown') current_app_role,
           coalesce((
            SELECT
                    CASE WHEN position('Administrator' in role_names)=0 THEN                     CASE WHEN position('Contributor' in role_names)=0 THEN                     CASE WHEN position('Reader' in role_names)=0 THEN 'No Access'  ELSE 'Reader' END   ELSE 'Contributor' END   ELSE 'Administrator' END  role_names
             from   APEX_APPL_ACL_USERS u 
             where  u.APPLICATION_ID = p_app_id and 
                    u.user_name_lc = t.email
             ),
             'No Access') app_role
        from sp_team_members t
        where coalesce((
            select
                    CASE WHEN position('Administrator' in role_names)=0 THEN                     CASE WHEN position('Contributor' in role_names)=0 THEN                     CASE WHEN position('Reader' in role_names)=0 THEN 'No Access'  ELSE 'Reader' END   ELSE 'Contributor' END   ELSE 'Administrator' END  role_names
             from   APEX_APPL_ACL_USERS u 
             where  u.APPLICATION_ID = p_app_id and 
                    u.user_name_lc = t.email),
             'No Access') != coalesce(t.APP_ROLE,'Unknown') 
        ) loop
            update sp_team_members
            set app_role = c1.app_role
            where id = c1.id;
    end loop;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_sync_team_members_app_role ( p_app_id numeric) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_util_sync_team_member_app_role ( p_app_id numeric, p_email varchar) AS $body$
DECLARE

  c1 RECORD;

BEGIN
    for c1 in (
       SELECT
           t.id,
           t.first_name,
           t.last_name,
           t.email,
           coalesce(t.APP_ROLE,'Unknown') current_app_role,
           coalesce((
            SELECT
                    CASE WHEN position('Administrator' in role_names)=0 THEN                     CASE WHEN position('Contributor' in role_names)=0 THEN                     CASE WHEN position('Reader' in role_names)=0 THEN 'No Access'  ELSE 'Reader' END   ELSE 'Contributor' END   ELSE 'Administrator' END  role_names
             from   APEX_APPL_ACL_USERS u 
             where  u.APPLICATION_ID = p_app_id and 
                    u.user_name_lc = t.email
             ),
             'No Access') app_role
        from sp_team_members t
        where coalesce((
            select
                    CASE WHEN position('Administrator' in role_names)=0 THEN                     CASE WHEN position('Contributor' in role_names)=0 THEN                     CASE WHEN position('Reader' in role_names)=0 THEN 'No Access'  ELSE 'Reader' END   ELSE 'Contributor' END   ELSE 'Administrator' END  role_names
             from   APEX_APPL_ACL_USERS u 
             where  u.APPLICATION_ID = p_app_id and USER_NAME_LC = lower(p_email) ),
             'No Access') != coalesce(t.APP_ROLE,'Unknown') 
        ) loop
            update sp_team_members
            set app_role = c1.app_role
            where id = c1.id;
    end loop;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_sync_team_member_app_role ( p_app_id numeric, p_email varchar) FROM PUBLIC;

