-- Tags
--
CREATE OR REPLACE PROCEDURE sp_util_add_default_tag ( p_tag varchar, p_sequence numeric default null) AS $body$
DECLARE

    l_seq numeric := p_sequence;
  c1 RECORD;

BEGIN
    if coalesce(l_seq::text, '') = '' then
        for c1 in (SELECT max(DISPLAY_SEQUENCE) mds from SP_DEFAULT_TAGS) loop
            l_seq := c1.mds + 10;
        end loop;
    end if;
    insert into SP_DEFAULT_TAGS(DISPLAY_SEQUENCE, tag) values (l_seq, upper(p_tag));
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_add_default_tag ( p_tag varchar, p_sequence numeric default null) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_util_get_default_tags ( p_tag_1 out varchar, p_tag_2 out varchar, p_tag_3 out varchar, p_tag_4 out varchar, p_tag_5 out varchar, p_tag_6 out varchar) AS $body$
DECLARE

    c numeric := 0;
  c1 RECORD;

BEGIN
    p_tag_1 := null;
    p_tag_2 := null;
    p_tag_3 := null;
    p_tag_4 := null;
    p_tag_5 := null;
    p_tag_6 := null;

    for c1 in (SELECT tag from SP_DEFAULT_TAGS order by display_sequence, tag) loop
        c := c + 1;
        if    c = 1 then p_tag_1 := c1.tag;
        elsif c = 2 then p_tag_2 := c1.tag;
        elsif c = 3 then p_tag_3 := c1.tag;
        elsif c = 4 then p_tag_4 := c1.tag;
        elsif c = 5 then p_tag_5 := c1.tag;
        elsif c = 6 then p_tag_6 := c1.tag;
        end if;
    end loop;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_get_default_tags ( p_tag_1 out varchar, p_tag_2 out varchar, p_tag_3 out varchar, p_tag_4 out varchar, p_tag_5 out varchar, p_tag_6 out varchar) FROM PUBLIC;



CREATE OR REPLACE FUNCTION sp_util_prepare_tags ( p_tags varchar) RETURNS varchar AS $body$
DECLARE

    l_tags  varchar(4000) := null;
BEGIN
    -- remove whitespace, have leading and trailing commas to facilitate instr
    l_tags := trim(both upper(p_tags));
    l_tags := ','||l_tags||',';
    l_tags := replace(l_tags,chr(9),' ');
    for i in 1..5 loop
        l_tags := replace(l_tags,', ',',');
    end loop;
    l_tags := replace(l_tags,',,',',');
    return l_tags;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_util_prepare_tags ( p_tags varchar) FROM PUBLIC;



CREATE OR REPLACE FUNCTION sp_util_reformat_tags ( p_tags varchar) RETURNS varchar AS $body$
DECLARE

    l_tags varchar(4000) := null;

BEGIN
    -- call this after calling prepare tags to reformat to friendly format
    l_tags := ltrim(p_tags,',');
    l_tags := rtrim(l_tags,',');
    l_tags := replace(l_tags,',',', ');
    return l_tags;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_util_reformat_tags ( p_tags varchar) FROM PUBLIC;



CREATE OR REPLACE FUNCTION sp_util_count_project_tags ( p_project_id numeric) RETURNS numeric AS $body$
DECLARE

    l_tag_count numeric := 0;
  c1 RECORD;

BEGIN
    for c1 in (SELECT tags from sp_projects where id = p_project_id and (tags IS NOT NULL AND tags::text <> '') ) loop
       l_tag_count := 1 + length(c1.tags) - length(replace(c1.tags,',',null));
    end loop;
    return l_tag_count;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_util_count_project_tags ( p_project_id numeric) FROM PUBLIC;



CREATE OR REPLACE FUNCTION sp_util_get_project_id ( p_friendly_identifier varchar, p_project_url_name varchar) RETURNS numeric AS $body$
DECLARE

    l_id numeric := null;
  c1 RECORD;

BEGIN
    if (p_friendly_identifier IS NOT NULL AND p_friendly_identifier::text <> '') then
       for c1 in (SELECT id from sp_projects where FRIENDLY_IDENTIFIER = p_friendly_identifier) loop
            l_id := c1.id;
            exit;
       end loop;
    end if;
    if coalesce(l_id::text, '') = '' and (p_project_url_name IS NOT NULL AND p_project_url_name::text <> '') then
       for c1 in (SELECT id from sp_projects where PROJECT_URL_NAME = p_project_url_name) loop
            l_id := c1.id;
            exit;
       end loop;
    end if;
    return l_id;
END;
