CREATE OR REPLACE FUNCTION sp_util_compress_int (n numeric ) RETURNS varchar AS $body$
DECLARE

   ret       varchar(30);
   quotient  numeric;
   remainder numeric;
   digit     char(1);

BEGIN
   ret := null;quotient := n;
   while quotient > 0
   loop
       remainder := mod(quotient, 10 + 26);
       quotient := floor(quotient  / (10 + 26));
       if remainder < 26 then
           digit := chr(ascii('A') + remainder);
       else
           digit := chr(ascii('0') + remainder - 26);
       end if;
       ret := digit || ret;
   end loop;
   if length(ret) < 5 then ret := lpad(ret, 4, 'A');end if;
   return upper(ret);
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_util_compress_int (n numeric ) FROM PUBLIC;


-- mostly used in comments but could be helpful elsewhere
CREATE OR REPLACE FUNCTION sp_util_find_mentions ( p_clob text ) RETURNS varchar AS $body$
DECLARE

    l_clob               text;
    l_mention_list       varchar(4000) := null;
    l_pos                numeric := 1;
    l_match              varchar(320);
    l_clob_length        numeric;
    l_screen_name_exists boolean := false;
    l_user_id            numeric;
    l_loop_count         numeric := 0;
    l_max_loops          numeric := 100;
  c1 RECORD;

BEGIN
    -- remove characters considered trailing white space
    l_clob := replace(p_clob, '+', ' '); -- remove all plus
    l_clob := replace(l_clob, '.', ' '); -- remove all dots
    l_clob := replace(l_clob, ',', ' '); -- remove all commas
    l_clob := replace(l_clob, '@', ' @'); -- prefix at sign with white space
    -- Get the length of the input CLOB
    l_clob_length := octet_length(l_clob);
    -- Loop through the CLOB to extract mentions using regex
    WHILE l_pos <= l_clob_length loop
        if l_loop_count > l_max_loops then
            exit; -- prevent infinite loop
        end if;
        l_match := null;
        l_match := (SELECT array_to_string(a, '') FROM regexp_matches(substr(l_clob,   -- Match "@" followed by non-whitespace characters
                                 l_pos), '@\S+', 'g') AS foo(a) LIMIT 1 OFFSET (1 - 1) );
        EXIT WHEN coalesce(l_match::text, '') = '';
        -- clean l_match
        l_match := lower(trim(both l_match));
        l_match := ltrim(l_match,'@'); -- remove leading at signs
        l_match := rtrim(l_match,'.,;:"''\/-|!#$%^&*()[]');
        -- locate screen name in team members table
        l_screen_name_exists := false;
        -- see if screen name exists in database, note stored as lower case
        for c1 in (SELECT id from sp_team_members tm where tm.screen_name = l_match) loop
            l_screen_name_exists := true;
            exit;
        end loop;
        -- see if name already exists in string, e.g. avoid returning duplicate names
        if l_screen_name_exists and
           position(':'||l_match||':' in ':'||l_mention_list||':') > 0 then
           l_screen_name_exists := false;
        end if;
        -- Append to the mention list
        if l_screen_name_exists then
            if (l_mention_list IS NOT NULL AND l_mention_list::text <> '') then
                l_mention_list := l_mention_list || ':' || l_match;
            else
                l_mention_list := l_match;
            end if;
        end if;
        -- Move position forward to continue searching
        l_pos := INSTR(l_clob, l_match, l_pos) + LENGTH(l_match);
        l_loop_count := l_loop_count + 1;
    end loop;
    return l_mention_list;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_util_find_mentions ( p_clob text ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION sp_util_list_change ( p_old_list varchar default null, p_new_list varchar default null, p_delim varchar default ',') RETURNS varchar AS $body$
DECLARE

    l_old_array           apex_t_varchar2;
    l_new_array           apex_t_varchar2;
    l_added               varchar(4000) := null;
    l_removed             varchar(4000) := null;
    l_found               boolean := false;
    l_action              varchar(32767) := null;
BEGIN
    --
    -- determine list changes including nulls
    --
    if coalesce(p_old_list::text, '') = '' and coalesce(p_new_list::text, '') = '' then
        l_action := 'No Values';
    elsif (p_old_list IS NOT NULL AND p_old_list::text <> '') and coalesce(p_new_list::text, '') = '' then
        l_removed := p_old_list;
        l_action := 'All values removed';
    elsif coalesce(p_old_list::text, '') = '' and (p_new_list IS NOT NULL AND p_new_list::text <> '') then
        l_added := '"'||p_new_list||'"';
        l_action := 'First values added';
    elsif p_old_list = p_new_list then
        l_action := 'No change';
    else
        l_action := 'Values changed';
       l_old_array := apex_string.split(p_str => p_old_list, p_sep => coalesce(p_delim,','));
       l_new_array := apex_string.split(p_str => p_new_list, p_sep => coalesce(p_delim,','));
       --
       -- added
       --
       for i in 1..l_new_array.count loop
           l_found := false;
           for j in 1..l_old_array.count loop
                if trim(both l_new_array(i)) = trim(both l_old_array(j)) then
                   l_found := true;
                   exit;
                end if;
           end loop;
           if not l_found then
               l_added := l_added||'"'||trim(both l_new_array(i))||'", ';
           end if;
       end loop;
       l_added := rtrim(l_added,', ');
       --
       -- removed
       --
       for i in 1..l_old_array.count loop
           l_found := false;
           for j in 1..l_new_array.count loop
                if trim(both l_old_array(i)) = trim(both l_new_array(j)) then
                   l_found := true;
                   exit;
                end if;
           end loop;
           if not l_found then
               l_removed := l_removed||'"'||trim(both l_old_array(i))||'", ';
           end if;
       end loop;
       l_removed := rtrim(l_removed,', ');
    end if;
    if (l_added IS NOT NULL AND l_added::text <> '') and coalesce(l_removed::text, '') = '' then
       l_action := 'added '||trim(both l_added);
    elsif coalesce(l_added::text, '') = '' and (l_removed IS NOT NULL AND l_removed::text <> '') then
       l_action := 'removed '||trim(both l_removed);
    elsif (l_added IS NOT NULL AND l_added::text <> '') and (l_added IS NOT NULL AND l_added::text <> '') then
       l_action := 'added '||trim(both l_added)||' and removed '||trim(both l_removed);
    end if;
    return l_action;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_util_list_change ( p_old_list varchar default null, p_new_list varchar default null, p_delim varchar default ',') FROM PUBLIC;

--------------------
-- for Notification Subscriptions
--
CREATE OR REPLACE PROCEDURE sp_util_send_notif_subscriptions () AS $body$
DECLARE

    l_app_id         varchar(30);
    l_app_url        varchar(4000);
    l_app_name       varchar(4000);
    l_opt_out_url    varchar(4000);
    l_gen_date       varchar(30);
    l_summary        text;
    l_day            varchar(3) := to_char(clock_timestamp(),'DY');
    l_sysdate        timestamp(0)        := clock_timestamp();
    l_tsysdate       timestamp(0)        := date_trunc('day', clock_timestamp());
    l_project_label  varchar(255);
    l_changes_yn     varchar(1);
  c1 RECORD;

BEGIN

    -- need to fetch app_id because this is being run by a db job so has no knowledge of the app
    l_app_id := sp_util_get_setting(p_static_id => 'APP_ID');

    -- the app_id is used to get the workspace, workspace must be set in order to use other apex apis (like apex_mail.send - without sgid, email template will not be found)
    for c1 in (
        SELECT workspace_id
         from apex_applications
        where application_id = l_app_id
    ) loop
        apex_util.set_security_group_id(p_security_group_id => c1.workspace_id);
    end loop;

    -- if build not not enabled, nothing will be run (careful to not update the build option name in the UI without editing this)
    if apex_util.get_build_option_status(
           p_application_id    => l_app_id,
           p_build_option_name => 'Subscriptions') = 'INCLUDE' and
       apex_util.get_build_option_status(
           p_application_id    => l_app_id,
           p_build_option_name => 'Email Configured') = 'INCLUDE'
    then

        l_app_url       := sp_util_get_setting(p_static_id => 'APP_HOME_URL');
        l_project_label := sp_util_get_nomenclature('PROJECT');
        l_app_name      := sp_util_get_nomenclature('STRATEGIC_PLANNER');
        l_gen_date      := to_char(l_sysdate,'DD-Mon-YYYY');
        l_opt_out_url   := sp_util_get_setting(p_static_id => 'APP_PREFIX_URL')||
                               apex_page.get_url(
                                   p_application => l_app_id,
                                   p_page        => 139,
                                   p_session     => null,
                                   p_plain_url   => TRUE );

        -- WEEKLY_SUMMARY
        for c1 in (
            SELECT tm.id team_member_id,
                   tm.email, 
                   s.id subscription_id
              from sp_team_members tm,
                   sp_notification_subscriptions s,
                   sp_notifications n
             where tm.id = s.team_member_id
               and s.notification_id = n.id
               and n.static_id = 'WEEKLY_SUMMARY'
               and n.is_active_yn = 'Y'
               and s.opted_in_yn = 'Y'
               and ( (s.frequency = 'WEEKDAYS' and 
                      l_day in ('MON','TUES','WED','THU','FRI') and (s.last_sent < l_sysdate - 1/2 or coalesce(s.last_sent::text, '') = '') )
                     or (s.frequency = 'WEEKLY' and 
                      l_day = 'MON' and (s.last_sent < l_sysdate - 6 or coalesce(s.last_sent::text, '') = '') ) ) 
        ) loop

            l_summary := sp_contributor_summary_generate(
                             p_team_member_id  => c1.team_member_id,
                             p_show_activities => 'Y',
                             p_show_projects   => 'Y',
                             p_links           => 'JOB' );

            apex_mail.send(
                p_to                 => c1.email,   
                p_from               => c1.email,  
                p_application_id     => l_app_id,  
                p_template_static_id => 'NOTIF_SUBSCRIPTIONS_JOB',  
                p_placeholders       => '{' || '"APPLICATION_LINK": "' || l_app_url ||'", '|| 
                                               '"OPT_OUT_URL": "'      || l_opt_out_url ||'", '||
                                               '"APP_NAME": '          || apex_json.stringify( l_app_name ) ||', '||
                                               '"SUBJECT": '           || apex_json.stringify( l_app_name||' Weekly Summary - '||to_char(l_sysdate,'Month DD, YYYY' ) )||', '||
                                               '"SUMMARY": '           || apex_json.stringify( l_summary ) ||
                                         '}' );

            -- this allows job to be restarted without duplicate emails going out
            -- this marks that an email was queued to be sent, but the sending could ultimately fail
            update sp_notification_subscriptions
               set last_sent = clock_timestamp()
             where id = c1.subscription_id;
        end loop;

        -- PROJECT_EXCEPTIONS
        for c1 in (
            SELECT tm.id team_member_id, 
                   tm.email, 
                   s.id subscription_id
              from sp_team_members tm,
                   sp_notification_subscriptions s,
                   sp_notifications n
             where tm.id = s.team_member_id
               and s.notification_id = n.id
               and n.static_id = 'PROJECT_EXCEPTIONS'
               and n.is_active_yn = 'Y'
               and s.opted_in_yn = 'Y'
               and ( (s.frequency = 'WEEKDAYS' and 
                      l_day in ('MON','TUES','WED','THU','FRI') and (s.last_sent < l_sysdate - 1/2 or coalesce(s.last_sent::text, '') = '') )
                     or (s.frequency = 'WEEKLY' and 
                      l_day = 'MON' and (s.last_sent < l_sysdate - 6 or coalesce(s.last_sent::text, '') = '') ) ) 
        ) loop

            l_summary := sp_contributor_summary_project_exceptions(
                             p_team_member_id  => c1.team_member_id,
                             p_links           => 'JOB' );

            apex_mail.send(
                p_to                 => c1.email,   
                p_from               => c1.email,  
                p_application_id     => l_app_id,  
                p_template_static_id => 'NOTIF_SUBSCRIPTIONS_JOB',  
                p_placeholders       => '{' || '"APPLICATION_LINK": "' || l_app_url ||'", '|| 
                                               '"OPT_OUT_URL": "'      || l_opt_out_url ||'", '||
                                               '"APP_NAME": '          || apex_json.stringify( l_app_name ) ||', '||
                                               '"SUBJECT": '           || apex_json.stringify( l_app_name||' '||l_project_label||' Exceptions - '||to_char(l_sysdate,'Month DD, YYYY' ) )||', '||
                                               '"SUMMARY": '           || apex_json.stringify( l_summary ) ||
                                         '}' );

            -- this allows job to be restarted without duplicate emails going out
            -- this marks that an email was queued to be sent, but the sending could ultimately fail
            update sp_notification_subscriptions
               set last_sent = clock_timestamp()
             where id = c1.subscription_id;
        end loop;

        -- RELEASE_EXCEPTIONS
        for c1 in (
            SELECT tm.id team_member_id, 
                   tm.email, 
                   s.id subscription_id,
                   r.release_train||' '||r.release release,
                   r.id release_id
              from sp_team_members tm,
                   sp_notification_subscriptions s,
                   sp_notifications n,
                   sp_release_trains r
             where tm.id = s.team_member_id
               and s.notification_id = n.id
               and n.static_id = 'RELEASE_EXCEPTIONS'
               and n.is_active_yn = 'Y'
               and s.release_id = r.id
               and coalesce(r.release_completed,'N') != 'Y'
               and s.opted_in_yn = 'Y'
               and ( (s.frequency = 'WEEKDAYS' and 
                      l_day in ('MON','TUES','WED','THU','FRI') and (s.last_sent < l_sysdate - 1/2 or coalesce(s.last_sent::text, '') = '') )
                     or (s.frequency = 'WEEKLY' and 
                      l_day = 'MON' and (s.last_sent < l_sysdate - 6 or coalesce(s.last_sent::text, '') = '') ) ) 
        ) loop

            l_summary := sp_release_timeline_release_exceptions(
                             p_release_id => c1.release_id,
                             p_links      => 'JOB' );

            apex_mail.send(
                p_to                 => c1.email,   
                p_from               => c1.email,  
                p_application_id     => l_app_id,  
                p_template_static_id => 'NOTIF_SUBSCRIPTIONS_JOB',  
                p_placeholders       => '{' || '"APPLICATION_LINK": "' || l_app_url ||'", '|| 
                                               '"OPT_OUT_URL": "'      || l_opt_out_url ||'", '||
                                               '"APP_NAME": '          || apex_json.stringify( l_app_name ) ||', '||
                                               '"SUBJECT": '           || apex_json.stringify( l_app_name||' '||c1.release||' Release Exceptions - '||to_char(l_sysdate,'Month DD, YYYY') )||', '||
                                               '"SUMMARY": '           || apex_json.stringify( l_summary ) ||
                                         '}' );

            -- this allows job to be restarted without duplicate emails going out
            -- this marks that an email was queued to be sent, but the sending could ultimately fail
            update sp_notification_subscriptions
               set last_sent = clock_timestamp()
             where id = c1.subscription_id;
        end loop;

        -- PROJECT_CHANGES
        for c1 in (
            SELECT tm.id team_member_id, 
                   tm.email, 
                   s.id subscription_id,
                   s.frequency
              from sp_team_members tm,
                   sp_notification_subscriptions s,
                   sp_notifications n
             where tm.id = s.team_member_id
               and s.notification_id = n.id
               and n.static_id = 'PROJECT_CHANGES'
               and n.is_active_yn = 'Y'
               and s.opted_in_yn = 'Y'
               and ( (s.frequency = 'WEEKDAYS' and 
                      l_day in ('MON','TUES','WED','THU','FRI') and (s.last_sent < l_sysdate - 1/2 or coalesce(s.last_sent::text, '') = '') )
                     or (s.frequency = 'WEEKLY' and 
                      l_day = 'MON' and (s.last_sent < l_sysdate - 6 or coalesce(s.last_sent::text, '') = '') ) ) 
        ) loop

            CALL sp_contributor_summary_project_changes(
                p_team_member_id => c1.team_member_id,
                p_frequency      => c1.frequency,
                p_links          => 'JOB',
                p_changes_yn     => l_changes_yn,
                p_change_summary => l_summary );

            if l_changes_yn = 'Y' then

                apex_mail.send(
                    p_to                 => c1.email,   
                    p_from               => c1.email,  
                    p_application_id     => l_app_id,  
                    p_template_static_id => 'NOTIF_SUBSCRIPTIONS_JOB',  
                    p_placeholders       => '{' || '"APPLICATION_LINK": "' || l_app_url ||'", '|| 
                                                   '"OPT_OUT_URL": "'      || l_opt_out_url ||'", '||
                                                   '"APP_NAME": '          || apex_json.stringify( l_app_name ) ||', '||
                                                   '"SUBJECT": '           || apex_json.stringify( l_app_name||' '||l_project_label||' Changes - '||to_char(l_sysdate,'Month DD, YYYY' ) )||', '||
                                                   '"SUMMARY": '           || apex_json.stringify( l_summary ) ||
                                             '}' );

                -- this allows job to be restarted without duplicate emails going out
                -- this marks that an email was queued to be sent, but the sending could ultimately fail
                update sp_notification_subscriptions
                   set last_sent = clock_timestamp()
                 where id = c1.subscription_id;
            end if;
        end loop;

    end if;

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_send_notif_subscriptions () FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_util_assignment_notification ( p_team_member_id numeric, p_app_name varchar, p_app_id numeric, p_project_id numeric default null, p_task_id numeric default null, p_link varchar DEFAULT NULL, p_view_what varchar DEFAULT NULL, p_title varchar DEFAULT NULL, p_email_contents varchar DEFAULT NULL, p_notification_type varchar  DEFAULT NULL) AS $body$
DECLARE

  c1 RECORD;

BEGIN
    -- only send if person is also a user (project owners may not be users)
    for c1 in (
        select email,
               coalesce(notification_pref,'APP:EMAIL') notification_pref
          from sp_team_members t
         where id = p_team_member_id
           and exists (select 1
                         from APEX_APPL_ACL_USERS
                        where application_id = p_app_id
                          and user_name_lc = t.email) 
    ) loop
        insert into sp_team_member_notifications(team_member_id, project_id, task_id, title, email_contents, notification_pref, notification_type)
        values (p_team_member_id, p_project_id, p_task_id, p_title, p_email_contents, c1.notification_pref, p_notification_type);

        if position(':EMAIL:' in ':'||c1.notification_pref||':') > 0 and
           apex_util.get_build_option_status(
               p_application_id    => p_app_id,
               p_build_option_name => 'Email Configured') = 'INCLUDE'
        then
            apex_mail.send(
                p_to                 => c1.email,   
                p_from               => c1.email,  
                p_application_id     => p_app_id,  
                p_template_static_id => 'PROJECT_RELATED',  
                p_placeholders       => '{' || '"VIEW_LINK": "' || p_link ||'", '|| 
                                               '"APP_NAME": '   || apex_json.stringify( p_app_name ) ||', '||
                                               '"SUBJECT": '    || apex_json.stringify( p_title ) ||', '||
                                               '"VIEW_WHAT": '  || apex_json.stringify( p_view_what ) ||', '||
                                               '"SUMMARY": '    || apex_json.stringify( p_email_contents ) ||
                                         '}' );
        end if;
    end loop;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_assignment_notification ( p_team_member_id numeric, p_app_name varchar, p_app_id numeric, p_project_id numeric default null, p_task_id numeric default null, p_link varchar DEFAULT NULL, p_view_what varchar DEFAULT NULL, p_title varchar DEFAULT NULL, p_email_contents varchar DEFAULT NULL, p_notification_type varchar  DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE sp_util_comment_notification ( p_team_member_id numeric, p_app_name varchar, p_app_id numeric, p_project_id numeric default null, p_task_id numeric default null, p_link varchar DEFAULT NULL, p_view_what varchar DEFAULT NULL, p_title varchar DEFAULT NULL, p_email_contents varchar DEFAULT NULL, p_notification_type varchar default 'COMMENT') AS $body$
DECLARE

  c1 RECORD;

BEGIN
    -- only send if person is also a user (project owners may not be users)
    for c1 in (
        select email,
               coalesce(comment_notif_pref,'APP:EMAIL') comment_pref
          from sp_team_members t
         where id = p_team_member_id
           and (position(':APP:' in ':'||coalesce(comment_notif_pref,'APP:EMAIL')||':') > 0 or
                position(':EMAIL:' in ':'||coalesce(comment_notif_pref,'APP:EMAIL')||':') > 0)
           and exists (select 1
                         from APEX_APPL_ACL_USERS
                        where application_id = p_app_id
                          and user_name_lc = t.email) 
    ) loop
        insert into sp_team_member_notifications(team_member_id, project_id, title, email_contents, notification_pref, notification_type)
        values (p_team_member_id, p_project_id, p_title, substr(p_email_contents,1,4000), c1.comment_pref, p_notification_type);

        if position(':EMAIL:' in ':'||c1.comment_pref||':') > 0 and
           apex_util.get_build_option_status(
               p_application_id    => p_app_id,
               p_build_option_name => 'Email Configured') = 'INCLUDE'
        then
            apex_mail.send(
                p_to                 => c1.email,   
                p_from               => c1.email,  
                p_application_id     => p_app_id,  
                p_template_static_id => 'PROJECT_RELATED',  
                p_placeholders       => '{' || '"VIEW_LINK": "' || p_link ||'", '|| 
                                               '"APP_NAME": '   || apex_json.stringify( p_app_name ) ||', '||
                                               '"SUBJECT": '    || apex_json.stringify( p_title ) ||', '||
                                               '"VIEW_WHAT": '  || apex_json.stringify( p_view_what ) ||', '||
                                               '"SUMMARY": '    || apex_json.stringify( p_email_contents ) ||
                                         '}' );
        end if;
    end loop;
END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE sp_util_comment_notification ( p_team_member_id numeric, p_app_name varchar, p_app_id numeric, p_project_id numeric default null, p_task_id numeric default null, p_link varchar DEFAULT NULL, p_view_what varchar DEFAULT NULL, p_title varchar DEFAULT NULL, p_email_contents varchar DEFAULT NULL, p_notification_type varchar default 'COMMENT') FROM PUBLIC;


-- used by SP_CONTRIBUTOR_SUMMARY, SP_RELEASE_TIMELINE and with app
CREATE OR REPLACE FUNCTION sp_util_exceptions_for_project ( p_project_id numeric, p_one_project_yn varchar default 'N', p_team_member_id numeric default null, p_link_type varchar DEFAULT NULL, p_app_prefix_url varchar DEFAULT NULL, p_app_id numeric DEFAULT NULL, p_apex_session numeric default null, p_reviews_yn varchar default 'N', p_approvals_yn varchar default 'N') RETURNS text AS $body$
DECLARE

    l_proj_yn              varchar(1) := 'N';
    l_exceptions_yn        varchar(1) := 'N';
    l_sysdate              timestamp(0) := date_trunc('day', clock_timestamp());
    l_date_fm              varchar(255) := 'FMDay DD-MON';
    l_project              varchar(4000);
    l_role                 varchar(4000);
    l_url                  varchar(4000);
    l_activity             varchar(4000);
    x                      text := null;
  c1 RECORD;
  c2 RECORD;

BEGIN
    for c1 in (
        SELECT p.id,
               p.friendly_identifier,
               p.project,
               p.owner_id,
               p.requires_reviews_yn,
               p.pct_complete,
               ' - '|| p.pct_complete::varchar ||'% '|| p.project_size ||' P'||r.priority::varchar quick_summary,
               case when (p.owner_id IS NOT NULL AND p.owner_id::text <> '') then ' - '||(SELECT first_name ||' '||last_name from sp_team_members where id = p.owner_id) end owner,
               case when p.pct_complete >= s.min_pc_for_status and
                         p.pct_complete != 100 and
                         coalesce(p.status_id::text, '') = ''
                    then 'Y'
                    end status_not_set
          from sp_projects p,
               sp_initiatives i,
               sp_project_priorities r,
               sp_project_scales s
         where p.id = p_project_id
           and p.initiative_id = i.id
           and p.priority_id = r.id
           and i.status_scale = s.scale_letter
    ) loop

        l_proj_yn := 'N';

        -- if for just one project, no need to include the project header
        if p_one_project_yn = 'N' then
            l_project := '<strong>'||apex_escape.html(c1.project)||'</strong>';
            -- broken out to avoid bulk bind error
            if c1.owner_id = p_team_member_id then l_role := ' (Owner)';
            else select ' ('||string_agg(rt.resource_type, ', ' order by rt.resource_type) ||')'
                   into STRICT l_role
                   from sp_project_contributors c,
                        sp_resource_types rt
                  where c.project_id = c1.id
                    and c.team_member_id = p_team_member_id
                    and c.responsibility_id = rt.id;
            end if;

            if p_link_type = 'APP' then
               l_url := apex_util.prepare_url('f?p='||p_app_id||':3:'||p_apex_session||'::NO:3:FI:'||apex_escape.html(c1.friendly_identifier));
               l_project := '<a href="'||l_url||'">'||l_project||'</a>' || apex_escape.html(l_role) || apex_escape.html(c1.owner) || apex_escape.html(c1.quick_summary);
            elsif p_link_type in ('EMAIL','JOB') then
               l_url := apex_page.get_url(
                            p_application => p_app_id,
                            p_page        => 3,
                            p_session     => null,
                            p_items       => 'FI',
                            p_values      => c1.friendly_identifier,
                            p_plain_url   => TRUE );
               if p_link_type = 'EMAIL' then
                  l_url := p_app_prefix_url || l_url;
               end if;
               l_project := '<a href="'||l_url||'">'||l_project||'</a>' || apex_escape.html(l_role) || apex_escape.html(c1.owner) || apex_escape.html(c1.quick_summary);
            else
               l_project := l_project || apex_escape.html(l_role) || apex_escape.html(c1.owner) || apex_escape.html(c1.quick_summary);
            end if;
        end if;

        -- NO PROJECT OWNER
        if coalesce(c1.owner_id::text, '') = '' then
            l_exceptions_yn := 'Y';
            x := x||l_project||chr(10)||'<ul>';
            l_proj_yn := 'Y';
            x := x||'<li>No Owner</li>'||chr(10);
        end if;

        -- STATUS NOT SET
        if c1.status_not_set = 'Y' then
            if l_proj_yn = 'N' then
               x := x||l_project||chr(10)||'<ul>';
               l_proj_yn := 'Y';
            end if;
            l_exceptions_yn := 'Y';
            x := x||'<li>Status not set</li>'||chr(10);
        end if;

        -- NO PROJECT REVIEWERS
        if c1.requires_reviews_yn = 'Y' and
           c1.pct_complete >= 50 and
           p_reviews_yn = 'Y' then
            for c2 in (
                SELECT count(*) cnt
                  from sp_tasks t,
                       sp_task_types tt
                 where t.project_id = c1.id
                   and coalesce(t.task_sub_type_id,t.task_type_id) = tt.id
                   and tt.static_id like 'REVIEW%'
                   and (t.owner_id IS NOT NULL AND t.owner_id::text <> '')
            ) loop
                if c2.cnt = 0 then
                    if l_proj_yn = 'N' then
                        x := x||l_project||chr(10)||'<ul>';
                        l_proj_yn := 'Y';
                    end if;
                    l_exceptions_yn := 'Y';
                    x := x||'<li>No Reviewers</li>'||chr(10);
                end if;
            end loop;
        end if;

        -- OVERDUE PROJECT MILESTONES
        for c2 in (
            SELECT (SELECT first_name||' '||last_name from sp_team_members tm where tm.id = t.owner_id) owner,
                   tt.task_type type,
                   s.status,
                   date_trunc('day', t.target_complete) target_complete
              from sp_tasks t,
                   sp_task_types tt,
                   sp_task_statuses s
             where t.project_id = c1.id
               and coalesce(t.task_sub_type_id,t.task_type_id) = tt.id
               and tt.static_id like 'MILESTONE%'
               and t.status_id = s.id
               and s.indicates_complete_yn = 'N'
               and date_trunc('day', t.target_complete) < l_sysdate
        ) loop
             if l_proj_yn = 'N' then
                 x := x||l_project||chr(10)||'<ul>';
                 l_proj_yn := 'Y';
             end if;
             l_exceptions_yn := 'Y';
             x := x||'<li>'|| apex_escape.html(c2.type)||' assigned to '||apex_escape.html(c2.owner) ||' was due '|| to_char(c2.target_complete,l_date_fm)||'  ('||apex_escape.html(c2.status)||')</li>'||chr(10);
        end loop;

        -- OVERDUE REVIEWS
        if c1.requires_reviews_yn = 'Y' and
           p_reviews_yn = 'Y' then
            for c2 in (
                SELECT (SELECT first_name||' '||last_name from sp_team_members tm where tm.id = t.owner_id) reviewer,
                       tt.task_type type,
                       s.status,
                       date_trunc('day', t.target_complete) review_date
                  from sp_tasks t,
                       sp_task_types tt,
                       sp_task_statuses s
                 where t.project_id = c1.id
                   and coalesce(t.task_sub_type_id,t.task_type_id) = tt.id
                   and tt.static_id like 'REVIEW%'
                   and t.status_id = s.id
                   and s.indicates_complete_yn = 'N'
                   and date_trunc('day', t.target_complete) < l_sysdate
            ) loop
                if l_proj_yn = 'N' then
                    x := x||l_project||chr(10)||'<ul>';
                    l_proj_yn := 'Y';
                end if;
                l_exceptions_yn := 'Y';
                x := x||'<li>'||apex_escape.html(c2.type)||' by '||apex_escape.html(c2.reviewer)||' was targeted for '||to_char(c2.review_date,l_date_fm)||'  ('||apex_escape.html(c2.status)||')</li>'||chr(10);
            end loop;

            -- REVIEWS WITHOUT DATES
            for c2 in (
                SELECT (SELECT first_name||' '||last_name from sp_team_members tm where tm.id = t.owner_id) reviewer,
                       tt.task_type type,
                       s.status
                  from sp_tasks t,
                       sp_task_types tt,
                       sp_task_statuses s
                 where t.project_id = c1.id
                   and coalesce(t.task_sub_type_id,t.task_type_id) = tt.id
                   and tt.static_id like 'REVIEW%'
                   and t.status_id = s.id
                   and s.indicates_complete_yn = 'N'
                   and coalesce(t.target_complete::text, '') = ''
            ) loop
                if l_proj_yn = 'N' then
                    x := x||l_project||chr(10)||'<ul>';
                    l_proj_yn := 'Y';
                end if;
                l_exceptions_yn := 'Y';
                x := x||'<li>'||apex_escape.html(c2.type)||' by '||apex_escape.html(c2.reviewer)||' has no target date ('||apex_escape.html(c2.status)||')</li>'||chr(10);
            end loop;
        end if;

        -- PENDING APPROVALS
        if p_approvals_yn = 'Y' then
            for c2 in (
                SELECT (SELECT first_name||' '||last_name from sp_team_members tm where tm.id = a.submitted_by_team_member_id) owner,
                       t.approval_type ||' Review' type,
                       case when a.status = 'PENDING'
                            then 'Pending Review'
                            when a.status = 'CLARIFICATION-REQUESTED'
                            then 'Clarification Requested'
                            end status,
                       date_trunc('day', a.updated) target_complete
                  from sp_project_approvals a,
                       sp_approval_types t
                 where a.project_id = c1.id
                   and a.approval_type_id = t.id
                   and a.status in ('PENDING','CLARIFICATION-REQUESTED')
            ) loop
                 if l_proj_yn = 'N' then
                     x := x||l_project||chr(10)||'<ul>';
                     l_proj_yn := 'Y';
                 end if;
                 l_exceptions_yn := 'Y';
                 x := x||'<li>'|| apex_escape.html(c2.type)||' submitted by '||apex_escape.html(c2.owner) ||' is currently '||apex_escape.html(c2.status)||'</li>'||chr(10);
            end loop;
        end if;

        if l_proj_yn = 'Y' then
            x := x||'</ul>';
        end if;
  
    end loop;

    return x;

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_util_exceptions_for_project ( p_project_id numeric, p_one_project_yn varchar default 'N', p_team_member_id numeric default null, p_link_type varchar DEFAULT NULL, p_app_prefix_url varchar DEFAULT NULL, p_app_id numeric DEFAULT NULL, p_apex_session numeric default null, p_reviews_yn varchar default 'N', p_approvals_yn varchar default 'N') FROM PUBLIC;



CREATE OR REPLACE FUNCTION sp_util_replace_nomenclature ( p_contents varchar ) RETURNS varchar AS $body$
DECLARE

    l_new_contents  varchar(4000);
  c1 RECORD;

BEGIN
    l_new_contents := p_contents;

    for c1 in (
        SELECT static_id, custom_value
          from sp_app_nomenclature
         order by static_id desc
    ) loop
        l_new_contents := replace(l_new_contents,'&NOMENCLATURE_'||c1.static_id||'.',c1.custom_value);
    end loop;

    for c1 in (
        SELECT static_id, custom_value
          from sp_app_nomenclature
         order by static_id desc
    ) loop
        l_new_contents := replace(l_new_contents,'NOMENCLATURE_'||c1.static_id,c1.custom_value);
    end loop;

    return l_new_contents;

END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION sp_util_replace_nomenclature ( p_contents varchar ) FROM PUBLIC;
