--
-- string
--
CREATE OR REPLACE FUNCTION sp_value_compare_is_equal ( p_value1 varchar default null, p_value2 varchar default null) RETURNS boolean AS $body$
BEGIN
   if coalesce(p_value1::text, '') = '' then
      if coalesce(p_value2::text, '') = '' then
         return true;
      else
         return false;
      end if;
   elsif coalesce(p_value2::text, '') = '' then
      return false;
   else
      if p_value1 = p_value2 then
         return true;
      else
         return false;
      end if;
   end if;
END;
$body$
LANGUAGE PLPGSQL
;
