--
CREATE OR REPLACE FUNCTION sp_value_compare_is_equal ( p_value1 text default null, p_value2 text default null) RETURNS boolean AS $body$
BEGIN
   if coalesce(p_value1::text, '') = '' then
      if coalesce(p_value2::text, '') = '' then
         return true;
      else
         return false;
      end if;
   elsif coalesce(p_value2::text, '') = '' then
      return false;
   else
      if DBMS_LOB.COMPARE(p_value1,p_value2) = 0 then
         return true;
      else
         return false;
      end if;
   end if;
END;
$body$
